pub const GENERATE_HANDLER: &str = "shots:generate";

/// Last `n` characters of a (possibly long) log.
pub(crate) fn tail(s: &str, n: usize) -> String {
    let skip = s.chars().count().saturating_sub(n);
    s.chars().skip(skip).collect()
}

fn result(tool: &str, status: Status) -> ToolResult {
    ToolResult {
        schema_version: SCHEMA_VERSION,
        tool: tool.into(),
        status,
        job_id: None,
        artifacts: vec![],
        metrics: BTreeMap::new(),
        images: vec![],
        warnings: vec![],
        error: None,
        wall_s: None,
    }
}

fn failed(tool: &str, code: &str, message: impl Into<String>, retryable: bool) -> ToolResult {
    let mut r = result(tool, Status::Failed);
    r.error = Some(ToolError { code: code.into(), message: message.into(), retryable, evidence: vec![] });
    r
}

fn metrics(v: Value) -> BTreeMap<String, Value> {
    v.as_object().map(|m| m.clone().into_iter().collect()).unwrap_or_default()
}

fn rel(run: &dyn RunCtx, p: &Path) -> String {
    p.strip_prefix(run.root()).unwrap_or(p).to_string_lossy().into_owned()
}

/// Prompt sent to video models: what the scene is, the look, and the move.
pub fn gen_prompt(path: &CameraPath, scene_text: &str, style: &str) -> String {
    let mv = path
        .movement
        .as_ref()
        .and_then(|m| serde_json::to_value(m.movement).ok())
        .and_then(|v| v.as_str().map(|s| s.replace('_', " ")))
        .unwrap_or_else(|| "camera move".into());
    let style = if style.is_empty() { path.movement.as_ref().and_then(|m| m.prompt.clone()).unwrap_or_default() } else { style.into() };
    let parts: Vec<&str> = [scene_text.trim(), style.trim()].into_iter().filter(|s| !s.is_empty()).collect();
    let lead = if parts.is_empty() { String::new() } else { format!("{}. ", parts.join(". ")) };
    format!(
        "{lead}Smooth cinematic {mv}, the camera path and scene layout follow the input exactly. Photorealistic, sharp detail, stable geometry, no new objects."
    )
}

/// Plan a shot into `shot_dir`: path.json, risk.json and a reference capture photo.
pub fn plan_into(frame: &SceneFrame, spec: &MoveSpec, shot_dir: &Path, name: &str) -> Result<(CameraPath, paths::Risk)> {
    let path = plan_path(frame, spec, name)?;
    let risk = plan_path_into(frame, &path, shot_dir)?;
    Ok((path, risk))
}

/// Write an already-planned path into `shot_dir`: path.json, risk.json and a reference capture photo.
pub fn plan_path_into(frame: &SceneFrame, path: &CameraPath, shot_dir: &Path) -> Result<paths::Risk> {
    std::fs::create_dir_all(shot_dir)?;
    let frames = sample_path(path);
    let risk = score_risk(frame, &frames);
    std::fs::write(shot_dir.join("path.json"), serde_json::to_vec_pretty(path)?)?;
    std::fs::write(shot_dir.join("risk.json"), serde_json::to_vec(&risk)?)?;
    // Real photo near the opening pose: appearance reference for video models.
    if let Some(dir) = &frame.image_dir {
        let src = dir.join(&frame.cameras[frame.nearest_capture(&frames[0].c2w, 45.0)].name);
        if src.exists() {
            let ext = src.extension().and_then(|e| e.to_str()).unwrap_or("jpg").to_ascii_lowercase();
            std::fs::copy(&src, shot_dir.join(format!("reference.{ext}")))?;
        }
    }
    Ok(risk)
}

pub fn scene_transform_near(ply: &Path) -> Option<PathBuf> {
    [ply.parent(), ply.parent().and_then(Path::parent)]
        .into_iter()
        .flatten()
        .map(|d| d.join("scene_transform.json"))
        .find(|p| p.exists())
}

/// A splat PLY path by name: `*.ply`, or its lossless zstd copy `*.ply.zst` (the readers decompress it).
pub fn is_splat_ply_name(p: &Path) -> bool {
    p.file_name().and_then(|n| n.to_str()).is_some_and(|n| {
        let n = n.to_ascii_lowercase();
        n.ends_with(".ply") || n.ends_with(".ply.zst")
    })
}

/// `dir`'s splat PLY: `splat.ply`, else `splat.ply.zst`.
pub fn splat_ply_in(dir: &Path) -> Option<PathBuf> {
    ["splat.ply", "splat.ply.zst"].iter().map(|n| dir.join(n)).find(|p| p.is_file())
}

pub fn find_ply(p: &Path) -> Option<PathBuf> {
    if is_splat_ply_name(p) && !p.is_dir() {
        return Some(p.to_path_buf());
    }
    if let Some(direct) = splat_ply_in(p) {
        return Some(direct);
    }
    // e.g. Spirula output dirs: step-*.ckpt/splat.ply, latest wins
    let mut found: Vec<PathBuf> = std::fs::read_dir(p).ok()?.flatten().filter_map(|e| splat_ply_in(&e.path())).collect();
    found.sort();
    found.pop()
}

/// Splat PLY + scene frame for a candidate artifact.
fn candidate_scene(run: &dyn RunCtx, candidate_id: &str) -> Result<(PathBuf, PathBuf, SceneFrame)> {
    let cand = run.artifact(candidate_id)?;
    let ply = find_ply(&run.path(candidate_id)?).with_context(|| format!("{candidate_id}: no splat.ply"))?;
    splat_core::fal::materialize(run.root(), &ply)?; // a --cloud model kept on fal
    let sfm_id = cand.meta.get("sfm_id").and_then(Value::as_str).with_context(|| format!("{candidate_id}: meta has no sfm_id"))?;
    let sfm = run.path(sfm_id)?;
    let frame = load_scene(&sfm, scene_transform_near(&ply).as_deref())?;
    Ok((ply, sfm, frame))
}

pub struct Shots {
    ffmpeg: encode::Ffmpeg,
    blender: PathBuf,
}

impl Default for Shots {
    fn default() -> Self {
        Self::new()
    }
}

impl Shots {
    /// Tools from SPLAT_FFMPEG / SPLAT_BLENDER or PATH; the CLI should pass resolved paths instead.
    pub fn new() -> Self {
        Self { ffmpeg: encode::Ffmpeg::from_env(), blender: blender::blender_exe() }
    }

    /// Use this ffmpeg for encoding here and in generate_shot's job worker (via its JobSpec env).
    pub fn with_ffmpeg(mut self, path: impl Into<PathBuf>) -> Self {
        self.ffmpeg = encode::Ffmpeg::new(path);
        self
    }

    pub fn with_blender(mut self, path: impl Into<PathBuf>) -> Self {
        self.blender = path.into();
        self
    }

    fn shot(&self, run: &dyn RunCtx, shot_id: &str) -> Result<(Artifact, ShotDir)> {
        Ok((run.artifact(shot_id)?, ShotDir(run.path(shot_id)?)))
    }
}

impl ShotTools for Shots {
    fn plan_shot(&self, run: &dyn RunCtx, req: PlanShot) -> Result<ToolResult> {
        let t0 = Instant::now();
        let (ply, sfm, frame) = candidate_scene(run, &req.candidate_id)?;
        let mut spec = spec_from_prompt(if req.prompt.is_empty() { "orbit" } else { &req.prompt }, req.movement);
        // Explicit request fields win over what the prompt implies; the contract's defaults don't
        // override words in the prompt (e.g. "3s", "vertical").
        if req.prompt.is_empty() || (req.duration_s - 5.0).abs() > 1e-9 {
            spec.duration_s = req.duration_s;
        }
        if let Some(a) = req.amount {
            spec.amount = Some(a);
        }
        if req.height_offset != 0.0 {
            spec.height_offset = req.height_offset;
        }
        if req.prompt.is_empty() || !matches!(req.aspect, Aspect::Wide) {
            (spec.width, spec.height) = match req.aspect {
                Aspect::Wide => (1280, 720),
                Aspect::Tall => (720, 1280),
                Aspect::Square => (960, 960),
            };
        }
        spec.start_camera = req.start_camera.clone();
        let (id, dir) = run.new_artifact_dir(ArtifactKind::Shot)?;
        let (path, risk) = plan_into(&frame, &spec, &dir, &id)?;
        let art = Artifact {
            id,
            kind: ArtifactKind::Shot,
            path: rel(run, &dir),
            meta: metrics(json!({
                "candidate_id": req.candidate_id, "ply": ply, "sfm_dir": sfm, "spec": spec,
            })),
        };
        run.register(art.clone())?;
        let mut r = result("plan_shot", Status::Succeeded);
        if risk.risk == "high" {
            r.warnings.push(format!(
                "{:.0}% of frames are far from any capture camera; expect holes and floaters",
                risk.frac_frames_far * 100.0
            ));
        }
        r.metrics = metrics(json!({
            "risk": risk.risk, "novelty_mean": risk.novelty_mean, "novelty_max": risk.novelty_max,
            "frac_frames_far": risk.frac_frames_far, "frames": path.frame_count(),
        }));
        r.artifacts.push(art);
        r.wall_s = Some(t0.elapsed().as_secs_f64());
        Ok(r)
    }

    fn render_shot(&self, run: &dyn RunCtx, req: RenderShot) -> Result<ToolResult> {
        let t0 = Instant::now();
        let (shot, dir) = self.shot(run, &req.shot_id)?;
        let path = dir.path()?;
        let ply = PathBuf::from(shot.meta.get("ply").and_then(Value::as_str).context("shot meta has no ply")?);
        let meta = match render::render_path(&ply, &path, &dir.render_dir(), &self.ffmpeg) {
            Ok(m) => m,
            Err(e) => {
                let msg = format!("{e:#}");
                let oom = msg.to_lowercase().contains("out of memory");
                return Ok(failed("render_shot", "render_failed", tail(&msg, 2000), oom));
            }
        };
        let art = Artifact {
            id: format!("{}_render", req.shot_id),
            kind: ArtifactKind::Video,
            path: rel(run, &dir.render_dir()),
            meta: metrics(serde_json::to_value(&meta)?),
        };
        // Re-rendering a shot overwrites its frames in place. The dispatcher registers the result's
        // artifacts, and an id is registered once: a re-render returns the artifact as first registered
        // (its meta keeps the first render's timings) rather than a changed copy, which would be refused.
        let art = run.artifact(&art.id).unwrap_or(art);
        let mut r = result("render_shot", Status::Succeeded);
        r.images = [0, meta.frames / 2, meta.frames - 1].iter().map(|&i| rel(run, &dir.frame("rgb", i))).collect();
        if meta.alpha_min_frame < 0.9 {
            r.warnings.push("low coverage: the splat leaves visible holes in some frames".into());
        }
        r.metrics = metrics(json!({
            "frames": meta.frames, "alpha_mean": meta.alpha_mean, "alpha_min_frame": meta.alpha_min_frame,
            "render_s": meta.render_s, "engine": meta.engine,
        }));
        r.artifacts.push(art);
        r.wall_s = Some(t0.elapsed().as_secs_f64());
        Ok(r)
    }

    fn generate_shot(&self, run: &dyn RunCtx, req: GenerateShot) -> Result<ToolResult> {
        let unknown: Vec<&String> = req.models.iter().filter(|m| models::model(m).is_none()).collect();
        if !unknown.is_empty() {
            return Ok(failed("generate_shot", "unknown_model", format!("{unknown:?}; known: {:?}", models::keys()), false));
        }
        let (_, dir) = self.shot(run, &req.shot_id)?;
        if !dir.rgb_video().exists() {
            return Ok(failed("generate_shot", "not_rendered", "run render_shot first", false));
        }
        let prompt = gen_prompt(&dir.path()?, &req.scene_text, &req.style);
        let exe = std::env::current_exe()?;
        let mut argv = vec![exe.to_string_lossy().into_owned(), "__shots".into(), "generate".into()];
        argv.push(dir.0.to_string_lossy().into_owned());
        argv.extend(["--prompt".into(), prompt]);
        for m in &req.models {
            argv.extend(["--model".into(), m.clone()]);
        }
        let spec = JobSpec {
            tool: "generate_shot".into(),
            argv,
            env: BTreeMap::from([("SPLAT_FFMPEG".to_string(), self.ffmpeg.path().to_string_lossy().into_owned())]),
            cwd: None,
            on_complete: GENERATE_HANDLER.into(),
            meta: metrics(json!({"shot_id": req.shot_id, "models": req.models})),
        };
        let mut r = result("generate_shot", Status::Running);
        r.job_id = Some(run.start_job(spec)?);
        Ok(r)
    }

    fn export_blender(&self, run: &dyn RunCtx, req: ExportBlender) -> Result<ToolResult> {
        let t0 = Instant::now();
        let (shot, dir) = self.shot(run, &req.shot_id)?;
        let path = dir.path()?;
        let ply = PathBuf::from(shot.meta.get("ply").and_then(Value::as_str).context("shot meta has no ply")?);
        let sfm = PathBuf::from(shot.meta.get("sfm_dir").and_then(Value::as_str).context("shot meta has no sfm_dir")?);
        let frame = load_scene(&sfm, scene_transform_near(&ply).as_deref())?;
        let mesh = match &req.mesh_id {
            Some(id) => {
                let p = run.path(id)?;
                if p.is_dir() {
                    std::fs::read_dir(&p)?.flatten().map(|e| e.path()).find(|p| p.extension().is_some_and(|e| e == "glb"))
                } else {
                    Some(p)
                }
            }
            None => None,
        };
        // A --cloud run's model and side mesh stay on fal until something here reads them.
        splat_core::fal::materialize(run.root(), &ply)?;
        if let Some(m) = &mesh {
            splat_core::fal::materialize(run.root(), m)?;
        }
        let (id, out) = run.new_artifact_dir(ArtifactKind::Export)?;
        let mut meta = blender::export_bundle(&frame, &ply, &path, &out, mesh.as_deref())?;
        let mut r = result("export_blender", Status::Succeeded);
        if req.build {
            let n = path.frame_count();
            match blender::build_blend(&self.blender, &out, &[0, n / 2, n - 1]) {
                Ok(b) => {
                    meta["build"] = b;
                    let mut stills: Vec<PathBuf> =
                        std::fs::read_dir(out.join("renders"))?.flatten().map(|e| e.path()).collect();
                    stills.sort();
                    r.images = stills.iter().map(|p| rel(run, p)).collect();
                }
                Err(e) => r.warnings.push(format!("bundle written but Blender build failed: {}", tail(&format!("{e:#}"), 500))),
            }
        }
        let art = Artifact { id, kind: ArtifactKind::Export, path: rel(run, &out), meta: metrics(meta.clone()) };
        run.register(art.clone())?;
        r.artifacts.push(art);
        r.metrics = metrics(meta);
        r.wall_s = Some(t0.elapsed().as_secs_f64());
        Ok(r)
    }

    fn on_job_complete(&self, run: &dyn RunCtx, handler: &str, job_dir: &Path, exit_code: i32) -> Result<ToolResult> {
        anyhow::ensure!(handler == GENERATE_HANDLER, "unknown shots handler {handler:?}");
        let spec: JobSpec = serde_json::from_slice(&std::fs::read(job_dir.join("request.json"))?)?;
        let shot_id = spec.meta.get("shot_id").and_then(Value::as_str).context("job meta has no shot_id")?;
        let models: Vec<String> = serde_json::from_value(spec.meta.get("models").cloned().unwrap_or_default())?;
        let dir = ShotDir(run.path(shot_id)?);
        let (mut arts, mut errors, mut usd) = (vec![], vec![], 0.0);
        for m in &models {
            let rec: Option<generate::GenRecord> =
                std::fs::read(dir.gen_dir().join(format!("{m}.json"))).ok().and_then(|b| serde_json::from_slice(&b).ok());
            match rec {
                Some(g) if g.error.is_none() && g.video.is_some() => {
                    usd += g.usd_estimate.unwrap_or(0.0);
                    let art = Artifact {
                        id: format!("{shot_id}_{m}"),
                        kind: ArtifactKind::Video,
                        path: rel(run, g.video.as_ref().unwrap()),
                        meta: metrics(serde_json::to_value(&g)?),
                    };
                    if run.artifact(&art.id).is_err() {
                        run.register(art.clone())?;
                    }
                    arts.push(art);
                }
                Some(g) => errors.push(format!("{m}: {}", tail(g.error.as_deref().unwrap_or("no video"), 300))),
                None => errors.push(format!("{m}: no record (worker exit {exit_code})")),
            }
        }
        let ok = !arts.is_empty();
        let mut r = if ok { result("generate_shot", Status::Succeeded) } else { failed("generate_shot", "generation_failed", errors.join("; "), true) };
        r.metrics = metrics(json!({"usd_estimate": (usd * 100.0).round() / 100.0, "models_ok": arts.len()}));
        r.warnings = errors;
        r.artifacts = arts;
        Ok(r)
    }
}

/// Hidden `splat __shots ...` entry used by detached jobs (and handy for dev runs).
pub fn worker_main(args: &[String]) -> Result<()> {
    use clap::Parser;
    let cmd = cli::Cli::try_parse_from(std::iter::once("splat __shots".to_string()).chain(args.iter().cloned()))?;
    cli::run(cmd.cmd)
}

#[cfg(test)]
mod find_ply_tests {
    use super::*;

    #[test]
    fn finds_compressed_splat_plys() {
        let dir = std::env::temp_dir().join(format!("splat-find-ply-{}", std::process::id()));
        let sub = dir.join("step-1.ckpt");
        std::fs::create_dir_all(&sub).unwrap();
        let packed = sub.join("splat.ply.zst");
        std::fs::write(&packed, b"x").unwrap();
        assert_eq!(find_ply(&packed), Some(packed.clone()), "an explicit .ply.zst is the input");
        assert_eq!(find_ply(&sub), Some(packed.clone()), "a dir holding splat.ply.zst");
        assert_eq!(find_ply(&dir), Some(packed.clone()), "a subdir holding splat.ply.zst");
        std::fs::write(sub.join("splat.ply"), b"x").unwrap();
        assert_eq!(find_ply(&sub), Some(sub.join("splat.ply")), "splat.ply wins over its zstd copy");
        assert!(is_splat_ply_name(Path::new("a/MODEL.PLY.ZST")) && !is_splat_ply_name(Path::new("a/model.zst")));
        std::fs::remove_dir_all(&dir).ok();
    }
}
